mapper.select:
SELECT task_id AS taskId, status, start_time AS startTime, execution_id AS executionId FROM task_execution WHERE task_id IN
#{taskId}
AND deleted = 0 AND start_time = ( SELECT MAX(start_time) FROM task_execution t2 WHERE t2.task_id = task_execution.task_id AND t2.deleted = 0 )

SELECT t.*
FROM task t
LEFT JOIN (
    SELECT task_id, status AS last_status
    FROM task_execution e1
    WHERE deleted = 0
      AND start_time = (
          SELECT MAX(start_time)
          FROM task_execution e2
          WHERE e2.task_id = e1.task_id
            AND e2.deleted = 0
      )
) last_exec ON t.id = last_exec.task_id
WHERE t.deleted = 0

    AND (t.task_name LIKE CONCAT('%', #{keyword}, '%')
         OR t.task_code LIKE CONCAT('%', #{keyword}, '%')
         OR t.tags LIKE CONCAT('%', #{keyword}, '%'))


    AND t.task_type = #{taskType}


    AND t.status = #{status}


    AND t.owner_user_id = #{ownerUserId}


    AND t.priority >= #{priority}


    AND t.tags LIKE CONCAT('%', #{tags}, '%')


    AND t.create_time >= #{startTime}


    AND t.create_time <= #{endTime}



        AND last_exec.last_status IS NULL


        AND last_exec.last_status = #{lastExecutionStatus}


ORDER BY t.create_time DESC
